-- Separate future reviewed hypotheses from observed reports. UI assessments are ephemeral.
CREATE TABLE cross_hypotheses(id TEXT PRIMARY KEY,maternal_accession_id TEXT REFERENCES accessions(id),paternal_accession_id TEXT REFERENCES accessions(id),rule_version TEXT NOT NULL,tier TEXT NOT NULL,target_endpoint TEXT NOT NULL,supporting_evidence_ids_json TEXT NOT NULL,counterevidence_ids_json TEXT NOT NULL,argument TEXT NOT NULL,gaps_json TEXT NOT NULL,curator_review TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE fertility_assertions(id TEXT PRIMARY KEY,accession_id TEXT NOT NULL REFERENCES accessions(id),parent_role TEXT NOT NULL CHECK(parent_role IN('seed','pollen')),endpoint TEXT NOT NULL CHECK(endpoint IN('pollen stainability','pollen production','functional fertility','seed production')),result TEXT NOT NULL,method TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES sources(id),uncertainty TEXT NOT NULL);
